steps.script:
for t in ToastManager.active_toasts:
	if is_instance_valid(t):
		t.queue_free()
ToastManager.active_toasts.clear()
return true

var sc = tree.current_scene.shooting_controller
var out: Array = []
for t in ToastManager.active_toasts:
	if is_instance_valid(t):
		for c in t.get_children():
			if c is Label:
				out.append(str(c.text))
return {"still_staged": sc.weapon_assignments.size() == 1, "still_armed": str(sc.active_shooter_id) == "U_BOYZ_T", "toast": "|".join(out)}
